import { test, expect } from 'bun:test';
import { mergeBlocks } from '../src/blocks.js';
test('merges overlapping blocks', () => expect(mergeBlocks([[0, 30], [20, 50], [100, 120]])).toEqual([[0, 50], [100, 120]]));
test('sorts unsorted input', () => expect(mergeBlocks([[100, 120], [20, 50], [0, 30]])).toEqual([[0, 50], [100, 120]]));
test('empty input', () => expect(mergeBlocks([])).toEqual([]));
test('disjoint blocks stay apart', () => expect(mergeBlocks([[0, 10], [20, 30]])).toEqual([[0, 10], [20, 30]]));

