import { test, expect } from 'bun:test';
import { mergeBlocks } from '../src/blocks.js';
test('touching blocks merge', () => {
  expect(mergeBlocks([[60, 90], [90, 120]])).toEqual([[60, 120]]);
  expect(mergeBlocks([[90, 120], [0, 60], [60, 90]])).toEqual([[0, 120]]);
});
test('a block inside another does not shrink it', () => {
  expect(mergeBlocks([[0, 100], [10, 20], [30, 40]])).toEqual([[0, 100]]);
  expect(mergeBlocks([[10, 20], [0, 100]])).toEqual([[0, 100]]);
});
test('the input is left alone and not shared with the result', () => {
  const input = [[50, 60], [0, 30], [20, 40]];
  const snapshot = JSON.stringify(input);
  const out = mergeBlocks(input);
  expect(JSON.stringify(input)).toBe(snapshot);
  out[0][1] = -1;
  expect(JSON.stringify(input)).toBe(snapshot);
});
